FUNCTION_BLOCK FB
VAR_INPUT
    tankLevel : REAL;
    outletFlow : REAL;
    inletPermit : BOOL;
    resetBtn : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun : BOOL;
    alarmHigh : BOOL;
    alarmLow : BOOL;
    outletValveOpen : BOOL;
END_VAR
VAR
    prevResetBtn : BOOL := FALSE;
END_VAR

// Rising edge detection
risingReset := resetBtn AND NOT prevResetBtn;

// High level alarm: latch on danger, clear only when safe + reset edge
alarmHigh := alarmHigh OR (tankLevel >= 85.0);
IF risingReset AND tankLevel < 85.0 THEN
    alarmHigh := FALSE;
END_IF

// Low level alarm: latch on danger, clear only when safe + reset edge
alarmLow := alarmLow OR (tankLevel <= 15.0);
IF risingReset AND tankLevel > 15.0 THEN
    alarmLow := FALSE;
END_IF

// Pump runs only when permitted and no alarms active
pumpRun := inletPermit AND NOT alarmHigh AND NOT alarmLow;

// Outlet valve closed only when low alarm is latched
outletValveOpen := NOT alarmLow;

// Update button history for next scan
prevResetBtn := resetBtn;
END_FUNCTION_BLOCK
```

